def test_pvp_master_contract_modes_authority_and_no_invented_balance():
 d=json.loads((ROOT/'data/m249_pvp_honor_ranked_contract.json').read_text()); m=d['master_contract']; assert set(['open_sea','ranked','guild_war','event_pvp','bounty_hunt','duel'])<=set(m['pvp_modes']); assert m['no_broadside_angle_damage'] is True and m['harpoon_vs_player_default']=='disabled_or_special_rule_only'; a=d['authority']; assert all(a[k]=='server' or a[k]=='server_time' or a[k]=='server_live_config' or a[k]=='server_idempotent' for k in ['live_zone_and_flag_state','honor_mutation','mmr_and_rank_points','matchmaking_and_match_result','combat_timer','pvp_modifiers','reward_qualification_and_settlement','anti_farm_verdict']); assert all(v is None for v in d['balance_boundary'].values() if v is not d['balance_boundary']['reason'])

def test_runtime_monotonic_and_competitive_client_mutations_forbidden():
 s=(ROOT/'scripts/progression/m249_pvp_honor_ranked_runtime.gd').read_text();
 for token in ['class_name M249PvpHonorRankedRuntime','if incoming_revision < revision: return false','LOCAL_PREVIEW','func zone_state()','func honor_state()','func ranked_state()','func queue_state()','func combat_timer_state()','func hud_state()','can_client_mutate_pvp_flag() -> bool: return false','can_client_mutate_honor() -> bool: return false','can_client_mutate_mmr_or_rank_points() -> bool: return false','can_client_set_match_result() -> bool: return false','can_client_set_combat_timer() -> bool: return false','can_client_override_anti_farm() -> bool: return false','can_client_settle_pvp_reward() -> bool: return false']: assert token in s

def test_factory_save_command_deck_and_hud_wiring():
 f=(ROOT/'scripts/core/procedural_factory.gd').read_text(); gs=(ROOT/'scripts/core/game_state.gd').read_text(); ui=(ROOT/'scripts/ui/command_deck.gd').read_text(); hud=(ROOT/'scripts/ui/nautical_hud.gd').read_text(); assert 'M249PvpHonorRankedRuntime.new()' in f and 'pvp_honor_ranked.name = "PvpHonorRanked"' in f; assert '"m249_pvp_honor_ranked"' in gs and 'pvp_honor_ranked.import_state' in gs; assert 'PVP · EHRE · BATTLE RANK' in ui and 'M249PvpHonorRankedCatalog.ranked_card' in ui and 'M249PvpHonorRankedCatalog.combat_timer_card' in ui; assert 'PVP TIMER ' in hud and 'weapons.attack_status() == "BEREIT"' in hud

def test_continuous_polish_contract_and_master_locks_preserved():
 d=json.loads((ROOT/'data/m249_client_polish_contract.json').read_text()); locks=d['immutable_locks']; assert locks['mobile_ship_movement']=='tap_to_sail_only' and locks['camera_joystick']=='camera_only' and locks['primary_attack']=='lower_right' and locks['gameplay_minimap']=='round' and locks['large_sea_chart']=='rectangular' and locks['platform_world_parity'] is True and locks['angle_damage'] is False; ui=(ROOT/'scripts/ui/command_deck.gd').read_text(); assert 'func _m249_animate_open()' in ui and 'func _m249_animate_status_card' in ui and 'compact_card' in ui

def test_admin_convergence_and_regressions():
 reg=json.loads((ROOT/'data/admin_content_type_registry.json').read_text())['content_types']; assert all(x in reg for x in ['pvp_zone_definition','honor_definition','battle_rank_definition','ranked_mode_definition','pvp_modifier_definition','combat_timer_definition']); d=json.loads((ROOT/'data/m239_master_convergence_matrix.json').read_text()); by={x['domain']:x for x in d['domains']}; assert by['pvp_honor_ranked']['status']=='PARTIAL' and 'm249_fix' in by['pvp_honor_ranked']; game=(ROOT/'scripts/ui/game_hud.gd').read_text(); assert 'no centered primary attack button' in game and 'lower-right combat anchor' in game; ai=(ROOT/'scripts/gameplay/enemy_ship_ai.gd').read_text(); assert 'canonical_attack_ready' in ai
